export const code = async (inputs) => {
  let b = inputs.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch { b = {}; } }
  if (!b || typeof b !== 'object') b = {};
  if (!b.trip_id) {
    return { success: false, message: 'trip_id is required', errors: ['trip_id is required'] };
  }
  return { success: true, trip_id: b.trip_id };
};

export const code = async (inputs) => {
  let rows = [];
  const raw = inputs.tripRows;
  if (Array.isArray(raw)) {
    rows = raw;
  } else if (raw && typeof raw === 'object') {
    const objVals = Object.values(raw);
    if (objVals.length > 0 && objVals[0] && typeof objVals[0] === 'object' && (objVals[0] as any).values) {
      rows = objVals;
    } else {
      rows = raw.data || raw.rows || objVals;
      if (!Array.isArray(rows)) rows = [rows];
    }
  }

  if (rows.length === 0) {
    return { success: false, message: 'Trip not found in Trips sheet', errors: ['Trip not found'] };
  }

  const row = rows[0] as any;
  const v = (row && row.values) ? row.values : (row || {});
  const budget = parseFloat(v.I || row.Budget || row.budget || 0);
  const tripName = String(v.C || row.Trip_Name || row.trip_name || '').trim();
  const tripDest = String(v.E || row.Destination || row.destination || '').trim();
  const tripSrc = String(v.D || row.Source || row.source || '').trim();
  const startDate = String(v.F || row.Start_Date || row.start_date || '').trim();
  const endDate = String(v.G || row.End_Date || row.end_date || '').trim();
  const status = String(v.J || row.Status || row.status || 'Active').trim();
  const userId = String(v.B || row.User_ID || row.user_id || '').trim();

  return {
    success: true,
    trip_id: inputs.tripId,
    trip_name: tripName,
    source: tripSrc,
    destination: tripDest,
    start_date: startDate,
    end_date: endDate,
    user_id: userId,
    status: status,
    budget: budget
  };
};

export const code = async (inputs) => {
  const d = inputs.data || {};
  const response = { success: false, message: d.message || 'Invalid request', errors: d.errors || [] };
  return { response_body: JSON.stringify(response) };
};

export const code = async (inputs) => {
  const budget = parseFloat(inputs.budget) || 0;
  const tripId = inputs.tripId || '';

  let rows = [];
  const raw = inputs.expenses;
  if (Array.isArray(raw)) {
    rows = raw;
  } else if (raw && typeof raw === 'object') {
    const objVals = Object.values(raw);
    if (objVals.length > 0 && objVals[0] !== null && typeof objVals[0] === 'object' && (objVals[0] as any).values) {
      rows = objVals;
    } else {
      rows = raw.data || raw.rows || objVals;
      if (!Array.isArray(rows)) rows = [rows];
    }
  }

  const categories = { Transportation: 0, Hotel: 0, Food: 0, Cab: 0, Other: 0 };
  let total = 0;
  let highestAmt = 0;
  let highestDetail = null;
  const recent = [];

  rows.forEach((row) => {
    if (!row || typeof row !== 'object') return;
    const r = row as any;
    const v = r.values || r;
    const cat = String(v.E || r.Category || r.category || 'Other').trim();
    const amt = parseFloat(v.H || r.Amount || r.amount || 0);
    const date = String(v.D || r.Date || r.date || '').trim();
    const merchant = String(v.G || r.Merchant || r.merchant || '').trim();
    const expId = String(v.A || r.Expense_ID || r.expense_id || '').trim();

    if (amt === 0 && !cat) return;

    if (categories.hasOwnProperty(cat)) { categories[cat] += amt; }
    else { categories.Other += amt; }
    total += amt;

    if (amt > highestAmt) {
      highestAmt = amt;
      highestDetail = { merchant: merchant, amount: amt, category: cat, date: date };
    }

    recent.push({
      expense_id:   expId,
      date:         date,
      category:     cat,
      merchant:     merchant,
      amount:       amt,
      status:       String(v.M || r.Status || r.status || 'Verified').trim(),
      subcategory:  String(v.F || r.Subcategory || '').trim(),
      payment_method: String(v.J || r.Payment_Method || '').trim(),
      description:  String(v.K || r.Description || '').trim(),
      receipt_url:  String(v.L || r.Receipt_URL || '').trim(),
      from_location:     String(v.N || r.From_Location || '').trim(),
      to_location:       String(v.O || r.To_Location || '').trim(),
      departure_date:    String(v.P || r.Departure_Date || '').trim(),
      departure_time:    String(v.Q || r.Departure_Time || '').trim(),
      arrival_date:      String(v.R || r.Arrival_Date || '').trim(),
      arrival_time:      String(v.S || r.Arrival_Time || '').trim(),
      seat_number:       String(v.T || r.Seat_Number || '').trim(),
      travel_class:      String(v.U || r.Travel_Class || '').trim(),
      tax:               parseFloat(v.V || r.Tax || 0),
      invoice_number:    String(v.W || r.Invoice_Number || '').trim(),
      booking_reference: String(v.X || r.Booking_Reference || '').trim(),
      items_json:        ((v.Y || r.Items_JSON || r.items_json) ? (typeof (v.Y || r.Items_JSON || r.items_json) === 'object' ? JSON.stringify(v.Y || r.Items_JSON || r.items_json) : String(v.Y || r.Items_JSON || r.items_json || '').trim()) : ''),
      expense_time:      '',
    });
  });

  recent.sort((a, b) => b.date.localeCompare(a.date));
  const remaining = budget - total;
  const budgetStatus = total < budget ? 'Within Budget' : 'Budget Exceeded';

  const response = {
    success: true,
    trip_id: tripId,
    budget: budget,
    total_spent: total,
    remaining: remaining,
    budget_status: budgetStatus,
    expense_count: rows.length,
    highest_expense: highestDetail,
    categories: categories,
    recent_expenses: recent.slice(0, 20)
  };
  return { response_body: JSON.stringify(response) };
};
